using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
namespace CampaignDemo.Editor
{
    public static class FortNodeVerification
    {
        static readonly List<string> results=new List<string>();
        static void Check(bool value,string label){if(!value)throw new Exception(label);results.Add("PASS "+label);}
        static void Near(float a,float b,string label){Check(Mathf.Abs(a-b)<.01f,label);}
        public static void Run(){try{FortNodeInstaller.Configure();Validate();EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText("fort-node-verification.txt",e+"\n"+string.Join("\n",results));Debug.LogException(e);EditorApplication.Exit(1);}}
        public static void Validate()
        {
            results.Clear();var root=new GameObject("Node construction test");var world=root.AddComponent<BattleWorld>();world.enabled=false;world.players=new[]{"A","B"};world.currentPlayer="A";world.fogEnabled=false;world.points=new RecoveryPoint[0];var c=root.AddComponent<CampaignRuntime>();c.enabled=false;c.world=world;c.rules=ScriptableObject.CreateInstance<CampaignRules>();c.combined=root.AddComponent<CombinedArmsWorld>();c.combined.enabled=false;c.combined.world=world;c.combined.engineering=ScriptableObject.CreateInstance<EngineeringDefinition>();c.combined.engineering.metersPerWorldUnit=10;c.combined.engineering.lineBuildSecondsPerMeter=1;c.combined.engineering.lineCostPerMeter=2;c.combined.engineering.lineDismantleSecondsPerMeter=1;c.logistics=root.AddComponent<LogisticsWorld>();c.logistics.enabled=false;c.logistics.world=world;c.Bind();
            var map=root.AddComponent<FreeMarchMapRuntime>();map.definition=ScriptableObject.CreateInstance<FreeMarchMapDefinition>();map.definition.bounds=new Rect(-5,-5,10,10);var setup=root.AddComponent<RoadMarchSceneSetup>();setup.freeMarchMap=map;world.setup=setup;world.campaign=c;
            var obj=new GameObject("worker");obj.transform.SetParent(root.transform);var u=obj.AddComponent<BattleUnit>();u.unitId="worker";u.ownerId="A";u.combatDefinition=ScriptableObject.CreateInstance<ArmyCombatDefinition>();u.combatDefinition.role=UnitRole.Engineer;u.combatDefinition.echelon=ArmyEchelon.Squad;u.combatDefinition.visionRadius=3;var move=obj.AddComponent<ArmyRoadMover>();move.definition=ScriptableObject.CreateInstance<ArmyDefinition>();var motor=obj.AddComponent<ArmyRouteMotor>();motor.Initialize(RoadRouteView.Create(obj.transform,"route",.02f,1,Color.white));var free=obj.AddComponent<ArmyFreeMarchMover>();free.allowedTerrain=TerrainAccess.Ground|TerrainAccess.Road|TerrainAccess.Grass|TerrainAccess.Mountain;free.Initialize(motor);free.BindMap(map);world.units=new[]{u};world.Initialize();
            var cityObj=new GameObject("city");cityObj.transform.SetParent(root.transform);var city=cityObj.AddComponent<RecoveryPoint>();city.ownerId="A";city.resourceStock=1000;world.points=new[]{city};
            var points=new[]{new Vector3(-1,1),new Vector3(0,1.5f),new Vector3(1,1)};float time=FortificationLineWorks.Length(points)*10,cost=time*2;Check(c.lineWorks.Build(u,points).accepted,"polyline accepted");Check(c.lineWorks.Approaching(u)&&motor.IsMoving&&!u.Working,"worker walks to construction site before becoming working");Near(city.resourceStock,1000-cost,"fee charged once when route accepted");c.lineWorks.Tick(1);Near(c.lineWorks.Remaining(u),time,"travel time does not consume construction duration");Check(c.combined.fortifications.Count==0,"no building before midpoint arrival");motor.Stop();obj.transform.position=new Vector3(0,1);c.lineWorks.Tick(0);Check(u.Working&&!c.lineWorks.Approaching(u),"arrival at endpoint midpoint starts construction");c.lineWorks.Tick(time/2);Check(c.combined.fortifications.Count==0,"half construction produces no half line");c.lineWorks.Cancel(u);Near(city.resourceStock,1000-cost/2,"cancel refunds uncompleted construction portion");
            Check(c.lineWorks.Build(u,points).accepted,"rebuild while already at midpoint");c.lineWorks.Tick(time);var fort=c.combined.fortifications[0];Check(fort.IsLine&&fort.linePoints.Length==3,"one completed object contains all clicked nodes");Near(fort.MaximumHealth,fort.Health,"maximum health recorded for basic panel");Check(fort.GetComponentsInChildren<LineRenderer>().Length>2,"baseline teeth and endpoint strokes generated");foreach(var line in fort.GetComponentsInChildren<LineRenderer>()){Check(line.startColor==c.combined.engineering.lineColor,"single color strokes no colored fill outline");Check(line.numCapVertices==0,"straight military stroke caps");}
            Check(!c.lineWorks.ToggleAutomaticRemoval("B",fort).accepted,"enemy cannot remove own fort remotely");Check(c.lineWorks.ToggleAutomaticRemoval("A",fort).accepted,"owner starts automatic demolition without worker");float duration=c.lineWorks.RemovalRemaining(fort);c.lineWorks.Tick(duration/2);Check(!fort.Destroyed,"demolition retains whole fort until complete");Check(c.lineWorks.ToggleAutomaticRemoval("A",fort).accepted&&!c.lineWorks.Removing(fort),"same action cancels demolition");Check(c.lineWorks.ToggleAutomaticRemoval("A",fort).accepted,"restart automatic demolition");c.lineWorks.Tick(duration);Check(fort.Destroyed,"automatic completion removes whole line");
            map.definition.regions=new[]{new FreeMarchMapDefinition.Region{terrain=TerrainKind.Blocked,polygon=new[]{new Vector2(-.2f,-2),new Vector2(.2f,-2),new Vector2(.2f,2),new Vector2(-.2f,2)}}};map.definition.MarkDirty();var route=ConstructionNavigation.Plan(map,free.AllowedTerrain,new Vector3(-1,0),new Vector3(1,0),.2f,10000);Check(route!=null&&route.Count>2,"automatic navigation routes around blocking terrain");for(int i=1;i<route.Count;i++)Check(map.CanTraverse(route[i-1],route[i],free.AllowedTerrain),"each automatic route segment respects terrain");
            var bad=new[]{new Vector3(-1,1),new Vector3(-1,2.5f),new Vector3(1,2.5f),new Vector3(1,1)};obj.transform.position=new Vector3(-1,0);float stock=city.resourceStock;Check(!c.lineWorks.Build(u,bad).accepted&&city.resourceStock==stock,"invalid endpoint midpoint rejected before charging city");
            foreach(var f in c.combined.fortifications)if(f!=null)UnityEngine.Object.DestroyImmediate(f.gameObject);UnityEngine.Object.DestroyImmediate(root);File.WriteAllText("fort-node-verification.txt",results.Count+" checks passed\n"+string.Join("\n",results));Debug.Log("FORT_NODE_VERIFY_PASS "+results.Count);
        }
    }
}
